            self$add(jmvcore::Html$new(
                options=options,
                name="reproducibilityCode",
                title="Equivalent R code",
                visible="(showRepro)"))}))

plssemBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "plssemBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "PLSsemLab",
                name = "plssem",
                version = c(0,7,6),
                options = options,
                results = plssemResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' PLS-SEM
#'
#' Partial least squares structural equation modeling with cSEM: reflective 
#' and formative constructs and higher-order constructs built from boxes, 
#' model validation before estimation, PLS and consistent PLS, measurement 
#' quality (reliability, HTMT, VIF), paths, effect sizes, mediation and 
#' moderation with bootstrap intervals, the overall fit test, PLSpredict and 
#' CVPAT, the importance-performance map and multigroup analysis (MICOM and 
#' path differences), each with plain-language interpretation.
#' 
#' @param data .
#' @param reflective .
#' @param formative .
#' @param reflectiveHoc .
#' @param formativeHoc .
#' @param hocApproach .
#' @param structural .
#' @param estimator .
#' @param innerScheme .
#' @param indicatorScale .
#' @param missing .
#' @param fornellLarcker .
#' @param bootstrap .
#' @param bootReps .
#' @param bootSeed .
#' @param ciLevel .
#' @param fitTest .
#' @param fitReps .
#' @param fitLevel .
#' @param predictRun .
#' @param predictFolds .
#' @param predictReps .
#' @param cvpatDrop .
#' @param ipma .
#' @param ipmaRange .
#' @param ipmaMin .
#' @param ipmaMax .
#' @param groupVar .
#' @param mgaRun .
#' @param mgaPerm .
#' @param mgaBoot .
#' @param mgaAdjust .
#' @param pathDiagram .
#' @param loadingsPlot .
#' @param htmtPlot .
#' @param moderationPlot .
#' @param diagramLayout .
#' @param diagramTitle .
#' @param diagramIndicators .
#' @param diagramCaption .
#' @param latentSize .
#' @param manifestSize .
#' @param nodeLabelSize .
#' @param latentFill .
#' @param manifestFill .
#' @param edgeWidth .
#' @param edgeColor .
#' @param nonsigDashed .
#' @param edgeLabels .
#' @param edgeLabelSize .
#' @param edgeDigits .
#' @param omegaCfa .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$modelGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$model} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$measurementGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$measurement} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$reliabilityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$reliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$htmtGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$htmt} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$fornell} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$vifGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$vif} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$hocGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurementSection$hocMeasurement} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$hocReliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementSection$hocHtmt} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$pathsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$structuralSection$paths} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$r2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$structuralGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$structuralSection$f2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$vifStruct} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$mediationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$structuralSection$mediation} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$moderationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$structuralSection$simpleSlopes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralSection$moderationPlots} \tab \tab \tab \tab \tab an array \cr
#'   \code{results$fitSection$fitGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fitSection$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$predictSection$predictGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$predictSection$predict} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$predictSection$cvpat} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ipmaSection$ipmaGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ipmaSection$ipmaTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ipmaSection$ipmaPlots} \tab \tab \tab \tab \tab an array \cr
#'   \code{results$mgaSection$mgaGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mgaSection$mgaGroups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mgaSection$micom} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mgaSection$mga} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plotsSection$pathDiagram} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotsSection$loadingsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotsSection$htmtPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fitCacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$predictCacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mgaCacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibilityCode} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$bootSummary$asDF}
#'
#' \code{as.data.frame(results$bootSummary)}
#'
#' @export
plssem <- function(
    data,
    reflective = list(
                list(label="Construct 1", vars=list())),
    formative = list(),
    reflectiveHoc = list(
                list(label="Higher-order 1", components=list())),
    formativeHoc = list(
                list(label="Higher-order 2", components=list())),
    hocApproach = "disjoint",
    structural = list(),
    estimator = "pls",
    innerScheme = "path",
    indicatorScale = "continuous",
    missing = "listwise",
    fornellLarcker = FALSE,
    bootstrap = FALSE,
    bootReps = 2000,
    bootSeed = 2026,
    ciLevel = 0.95,
    fitTest = FALSE,
    fitReps = 499,
    fitLevel = 0.95,
    predictRun = FALSE,
    predictFolds = 10,
    predictReps = 10,
    cvpatDrop = list(),
    ipma = FALSE,
    ipmaRange = "data",
    ipmaMin = 1,
    ipmaMax = 7,
    groupVar = NULL,
    mgaRun = FALSE,
    mgaPerm = 1000,
    mgaBoot = 1000,
    mgaAdjust = "none",
    pathDiagram = TRUE,
    loadingsPlot = FALSE,
    htmtPlot = FALSE,
    moderationPlot = TRUE,
    diagramLayout = "treeLR",
    diagramTitle = "",
    diagramIndicators = TRUE,
    diagramCaption = TRUE,
    latentSize = 11,
    manifestSize = 6,
    nodeLabelSize = 1,
    latentFill = "theme",
    manifestFill = "theme",
    edgeWidth = "estimate",
    edgeColor = "theme",
    nonsigDashed = TRUE,
    edgeLabels = TRUE,
    edgeLabelSize = 0.8,
    edgeDigits = 2,
    omegaCfa = FALSE,
    showKeySummary = TRUE,
    showChoicesGuide = TRUE,
    showGuides = FALSE,
    showRepro = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("plssem requires jmvcore to be installed (restart may be required)")

    if ( ! missing(groupVar)) groupVar <- jmvcore::resolveQuo(jmvcore::enquo(groupVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(groupVar), groupVar, NULL))

    for (v in groupVar) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    if (inherits(cvpatDrop, "formula")) cvpatDrop <- jmvcore::decomposeFormula(cvpatDrop)

    options <- plssemOptions$new(
        reflective = reflective,
        formative = formative,
        reflectiveHoc = reflectiveHoc,
        formativeHoc = formativeHoc,
        hocApproach = hocApproach,
        structural = structural,
        estimator = estimator,
        innerScheme = innerScheme,
        indicatorScale = indicatorScale,
        missing = missing,
        fornellLarcker = fornellLarcker,
        bootstrap = bootstrap,
        bootReps = bootReps,
        bootSeed = bootSeed,
        ciLevel = ciLevel,
        fitTest = fitTest,
        fitReps = fitReps,
        fitLevel = fitLevel,
        predictRun = predictRun,
        predictFolds = predictFolds,
        predictReps = predictReps,
        cvpatDrop = cvpatDrop,
        ipma = ipma,
        ipmaRange = ipmaRange,
        ipmaMin = ipmaMin,
        ipmaMax = ipmaMax,
        groupVar = groupVar,
        mgaRun = mgaRun,
        mgaPerm = mgaPerm,
        mgaBoot = mgaBoot,
        mgaAdjust = mgaAdjust,
        pathDiagram = pathDiagram,
        loadingsPlot = loadingsPlot,
        htmtPlot = htmtPlot,
        moderationPlot = moderationPlot,
        diagramLayout = diagramLayout,
        diagramTitle = diagramTitle,
        diagramIndicators = diagramIndicators,
        diagramCaption = diagramCaption,
        latentSize = latentSize,
        manifestSize = manifestSize,
        nodeLabelSize = nodeLabelSize,
        latentFill = latentFill,
        manifestFill = manifestFill,
        edgeWidth = edgeWidth,
        edgeColor = edgeColor,
        nonsigDashed = nonsigDashed,
        edgeLabels = edgeLabels,
        edgeLabelSize = edgeLabelSize,
        edgeDigits = edgeDigits,
        omegaCfa = omegaCfa,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro)

    analysis <- plssemClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

